import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triplet_margin_loss_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel 1: Compute partial sums of squared distances for anchor-positive and anchor-negative
__global__ void compute_partial_sums_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ dPos,
    float* __restrict__ dNeg,
    int total_size,
    int dim
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index >= total_size) return;

    int i = index / dim;
    int j = index % dim;

    float ap = anchor[i * dim + j] - positive[i * dim + j];
    float an = anchor[i * dim + j] - negative[i * dim + j];

    atomicAdd(&dPos[i], ap * ap);
    atomicAdd(&dNeg[i], an * an);
}

// Kernel 2: Finalize triplet margin loss by summing, applying margin, and clamping
__global__ void finalize_triplet_margin_loss_kernel(
    float* __restrict__ dPos,
    float* __restrict__ dNeg,
    float margin,
    float* __restrict__ out,
    int batch_size
) {
    __shared__ float partial_sums[256];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;

    float val = 0.0f;
    if (i < batch_size) {
        float dp = sqrtf(dPos[i]);
        float dn = sqrtf(dNeg[i]);
        float loss = dp - dn + margin;
        if (loss < 0.0f) {
            loss = 0.0f;
        }
        val = loss;
    }

    partial_sums[tid] = val;
    __syncthreads();

    // Block-level reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            partial_sums[tid] += partial_sums[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(out, partial_sums[0]);
    }
}

// Combined launcher for the above kernels
torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    float margin
) {
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");

    int batch_size = anchor.size(0);
    int dim = anchor.size(1);
    int total_size = batch_size * dim;

    auto options = torch::TensorOptions().dtype(anchor.dtype()).device(anchor.device());
    auto dPos = torch::zeros({batch_size}, options);
    auto dNeg = torch::zeros({batch_size}, options);
    auto out  = torch::zeros({1}, options);

    const int block_size = 256;
    int num_blocks = (total_size + block_size - 1) / block_size;

    compute_partial_sums_kernel<<<num_blocks, block_size>>>(
        anchor.data_ptr<float>(),
        positive.data_ptr<float>(),
        negative.data_ptr<float>(),
        dPos.data_ptr<float>(),
        dNeg.data_ptr<float>(),
        total_size,
        dim
    );

    // Second kernel to finalize the loss
    int num_blocks2 = (batch_size + block_size - 1) / block_size;
    finalize_triplet_margin_loss_kernel<<<num_blocks2, block_size>>>(
        dPos.data_ptr<float>(),
        dNeg.data_ptr<float>(),
        margin,
        out.data_ptr<float>(),
        batch_size
    );

    // Average over the batch
    auto loss = out / batch_size;
    return loss;
}
""";

triplet_margin_loss_cpp_source = """
torch::Tensor triplet_margin_loss_cuda(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    float margin
);
""";

triplet_margin_loss = load_inline(
    name="triplet_margin_loss",
    cpp_sources=triplet_margin_loss_cpp_source,
    cuda_sources=triplet_margin_loss_source,
    functions=["triplet_margin_loss_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = margin
        self.triplet_margin_loss = triplet_margin_loss

    def forward(self, anchor, positive, negative):
        return self.triplet_margin_loss.triplet_margin_loss_cuda(anchor, positive, negative, float(self.margin))
